export const modalsHtml = "<!-- ELEVATED DRAG LAYER FOR ACTUAL CANVAS CARDS (Renders above Toolbar / Topbar / Unsorted when dragged onto bars) -->\n    <div id=\"canvas-drag-overlay\" class=\"fixed inset-0 pointer-events-none z-[9500] overflow-visible hidden\">\n        <div id=\"canvas-drag-overlay-world\" class=\"absolute top-0 left-0 w-[10000px] h-[10000px] pointer-events-none\" style=\"transform-origin: 0 0;\"></div>\n    </div>\n\n    <!-- FLOATING DRAG GHOST (Used for Toolbar / Unsorted / Trash / Task physics dragging) -->\n    <div id=\"floating-drag-ghost\" class=\"fixed pointer-events-none z-[9999] hidden\"></div>\n\n    <!-- MENU DE CONTEXTO (CLIQUE DIREITO) -->\n    <div id=\"context-menu\" class=\"context-menu\">\n        <!-- Injetado via JS -->\n    </div>\n\n    <!-- TRASH MODAL -->\n    <div id=\"trash-modal\" class=\"fixed inset-0 bg-black/65 backdrop-blur-sm z-50 flex items-center justify-center hidden p-2.5 sm:p-4 transition-opacity duration-150\">\n        <div class=\"bg-[#18181b] border border-white/[0.08] rounded-xl w-full max-w-[500px] h-[85dvh] sm:h-[80vh] flex flex-col card-shadow overflow-hidden\">\n            <div class=\"px-4 sm:px-5 py-3.5 sm:py-4 border-b border-white/[0.06] flex items-center justify-between shrink-0\">\n                <h3 class=\"font-medium text-sm text-zinc-200\" data-i18n=\"trash\">Trash</h3>\n                <button type=\"button\" onclick=\"closeTrashModal()\" class=\"text-zinc-400 hover:text-zinc-200 p-1 rounded-md hover:bg-white/[0.06] transition-colors\">\n                    <svg class=\"w-4 h-4\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"></line><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"></line></svg>\n                </button>\n            </div>\n            \n            <div id=\"trash-list\" class=\"flex-1 overflow-y-auto p-3.5 sm:p-4 space-y-6\"></div>\n            \n            <div class=\"p-3.5 sm:p-4 border-t border-white/[0.06] shrink-0\">\n                <button type=\"button\" onclick=\"emptyTrash()\" class=\"w-full bg-white/[0.05] hover:bg-white/[0.09] text-zinc-300 text-xs py-2.5 rounded-lg border border-white/[0.06] transition-colors font-medium\" data-i18n=\"emptyTrashBtn\">Empty trash</button>\n            </div>\n        </div>\n    </div>\n\n    <!-- ICON PICKER POPOVER -->\n    <div id=\"icon-picker-popover\" class=\"fixed hidden bg-[#222226] border border-borderSubtle rounded-xl shadow-2xl z-[100] p-3 w-[240px]\">\n        <div class=\"flex items-center justify-between mb-3\">\n            <span class=\"text-xs font-medium text-zinc-300\" data-i18n=\"chooseIcon\">Choose Icon</span>\n            <button type=\"button\" onclick=\"document.getElementById('icon-picker-popover').classList.add('hidden')\" class=\"text-zinc-500 hover:text-zinc-300\"><svg class=\"w-4 h-4\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"></line><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"></line></svg></button>\n        </div>\n        <div class=\"grid grid-cols-4 gap-2 mb-3\" id=\"icon-picker-grid\">\n            <!-- Injetado via JS -->\n        </div>\n        <div class=\"border-t border-borderSubtle pt-2 flex flex-col gap-2\">\n            <button type=\"button\" onclick=\"triggerIconUpload()\" class=\"w-full text-left text-xs text-zinc-400 hover:text-zinc-200 flex items-center gap-2 p-1.5 rounded hover:bg-[#2a2a2f]\"><svg class=\"w-3.5 h-3.5\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"></path><polyline points=\"17 8 12 3 7 8\"></polyline><line x1=\"12\" y1=\"3\" x2=\"12\" y2=\"15\"></line></svg><span data-i18n=\"uploadImage\">Upload Image</span></button>\n            <button type=\"button\" onclick=\"promptIconUrl()\" class=\"w-full text-left text-xs text-zinc-400 hover:text-zinc-200 flex items-center gap-2 p-1.5 rounded hover:bg-[#2a2a2f]\"><svg class=\"w-3.5 h-3.5\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71\"></path><path d=\"M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71\"></path></svg><span data-i18n=\"useUrl\">Use URL</span></button>\n            <button type=\"button\" onclick=\"removeBoardIcon()\" class=\"w-full text-left text-xs text-red-400 hover:text-red-300 flex items-center gap-2 p-1.5 rounded hover:bg-[#2a2a2f]\"><svg class=\"w-3.5 h-3.5\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"></line><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"></line></svg><span data-i18n=\"removeIcon\">Remove Icon</span></button>\n        </div>\n    </div>\n\n    <!-- BOARD BACKGROUND POPOVER -->\n    <div id=\"board-bg-popover\" class=\"fixed hidden bg-[#1e1e23] border border-white/[0.1] rounded-xl shadow-2xl z-[120] p-3.5 w-[264px]\">\n        <div class=\"flex items-center justify-between mb-3\">\n            <span class=\"text-xs font-semibold text-zinc-200\" data-i18n=\"boardBgTitle\">Board Background</span>\n            <button type=\"button\" onclick=\"closeBoardBgPopover()\" class=\"text-zinc-500 hover:text-zinc-200 p-0.5 rounded\"><svg class=\"w-4 h-4\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"></line><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"></line></svg></button>\n        </div>\n        <div class=\"space-y-3\">\n            <div>\n                <div class=\"text-[10.5px] font-medium text-zinc-400 mb-1.5\" data-i18n=\"bgColorLabel\">Color</div>\n                <div id=\"board-bg-swatches\" class=\"flex items-center flex-wrap gap-2\"></div>\n            </div>\n            <div class=\"border-t border-white/[0.06] pt-2.5\">\n                <div class=\"text-[10.5px] font-medium text-zinc-400 mb-1.5\" data-i18n=\"bgPatternLabel\">Pattern</div>\n                <div id=\"board-bg-patterns\" class=\"grid grid-cols-3 gap-1.5\">\n                    <button type=\"button\" data-bg-pattern=\"dots\" onclick=\"setBoardBgPattern('dots')\" class=\"px-2 py-1.5 rounded-lg text-[11px] font-medium border transition-colors\" data-i18n=\"patternDots\">Dots</button>\n                    <button type=\"button\" data-bg-pattern=\"grid\" onclick=\"setBoardBgPattern('grid')\" class=\"px-2 py-1.5 rounded-lg text-[11px] font-medium border transition-colors\" data-i18n=\"patternGrid\">Grid</button>\n                    <button type=\"button\" data-bg-pattern=\"solid\" onclick=\"setBoardBgPattern('solid')\" class=\"px-2 py-1.5 rounded-lg text-[11px] font-medium border transition-colors\" data-i18n=\"patternSolid\">Solid</button>\n                </div>\n            </div>\n            <button type=\"button\" onclick=\"resetBoardBackground()\" class=\"w-full py-1.5 rounded-lg text-[11px] text-zinc-400 hover:text-zinc-100 bg-white/[0.04] hover:bg-white/[0.08] border border-white/[0.06] transition-colors\" data-i18n=\"resetBackground\">Reset to Default</button>\n        </div>\n    </div>\n\n    <!-- DOCUMENT MODAL -->\n    <div id=\"document-modal\" class=\"fixed inset-0 bg-black/80 backdrop-blur-sm z-[200] flex items-center justify-center hidden p-2 sm:p-4\">\n        <div class=\"bg-[#141416] border border-borderSubtle rounded-xl w-full max-w-[900px] h-[92dvh] sm:h-[90vh] flex flex-col shadow-2xl overflow-hidden\">\n            <div class=\"h-12 border-b border-borderSubtle flex items-center justify-between px-3 sm:px-4 shrink-0 bg-[#1c1c1f]\">\n                <input type=\"text\" id=\"doc-title-input\" class=\"bg-transparent text-sm font-semibold text-zinc-100 focus:outline-none flex-1 min-w-0 pr-2\" placeholder=\"Document Title\" data-i18n-placeholder=\"docTitlePlaceholder\">\n                <div class=\"flex items-center gap-2 shrink-0\">\n                    <span id=\"doc-word-count\" class=\"text-[11px] text-zinc-500\">0 words</span>\n                    <button type=\"button\" onclick=\"closeDocumentModal()\" class=\"text-zinc-400 hover:text-zinc-200 p-1.5 rounded hover:bg-[#2a2a2f]\"><svg class=\"w-4 h-4\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"></line><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"></line></svg></button>\n                </div>\n            </div>\n            <div class=\"flex-1 flex overflow-hidden\">\n                <!-- Toolbar do Editor -->\n                <div class=\"w-10 sm:w-12 border-r border-borderSubtle flex flex-col items-center py-2 sm:py-3 gap-2 sm:gap-3 bg-[#1c1c1f] shrink-0 overflow-y-auto\">\n                    <button onclick=\"document.execCommand('bold')\" class=\"p-1.5 text-zinc-400 hover:text-white rounded hover:bg-[#2a2a2f]\" title=\"Bold\" data-i18n-title=\"docBold\"><span class=\"text-sm font-bold\">B</span></button>\n                    <button onclick=\"document.execCommand('italic')\" class=\"p-1.5 text-zinc-400 hover:text-white rounded hover:bg-[#2a2a2f]\" title=\"Italic\" data-i18n-title=\"docItalic\"><span class=\"text-sm italic font-serif\">I</span></button>\n                    <button onclick=\"document.execCommand('underline')\" class=\"p-1.5 text-zinc-400 hover:text-white rounded hover:bg-[#2a2a2f]\" title=\"Underline\" data-i18n-title=\"docUnderline\"><span class=\"text-sm underline\">U</span></button>\n                    <div class=\"w-6 h-[1px] bg-borderSubtle\"></div>\n                    <button onclick=\"document.execCommand('insertUnorderedList')\" class=\"p-1.5 text-zinc-400 hover:text-white rounded hover:bg-[#2a2a2f]\" title=\"Bullet List\" data-i18n-title=\"docBulletList\"><svg class=\"w-4 h-4\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"8\" y1=\"6\" x2=\"21\" y2=\"6\"></line><line x1=\"8\" y1=\"12\" x2=\"21\" y2=\"12\"></line><line x1=\"8\" y1=\"18\" x2=\"21\" y2=\"18\"></line><line x1=\"3\" y1=\"6\" x2=\"3.01\" y2=\"6\"></line><line x1=\"3\" y1=\"12\" x2=\"3.01\" y2=\"12\"></line><line x1=\"3\" y1=\"18\" x2=\"3.01\" y2=\"18\"></line></svg></button>\n                    <button onclick=\"document.execCommand('insertOrderedList')\" class=\"p-1.5 text-zinc-400 hover:text-white rounded hover:bg-[#2a2a2f]\" title=\"Numbered List\" data-i18n-title=\"docNumberedList\"><svg class=\"w-4 h-4\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"10\" y1=\"6\" x2=\"21\" y2=\"6\"></line><line x1=\"10\" y1=\"12\" x2=\"21\" y2=\"12\"></line><line x1=\"10\" y1=\"18\" x2=\"21\" y2=\"18\"></line><path d=\"M4 6h1v4\"></path><path d=\"M4 10h2\"></path><path d=\"M6 18H4c0-1 2-2 2-3s-1-1.5-2-1\"></path></svg></button>\n                    <button onclick=\"document.execCommand('formatBlock', false, '<blockquote>')\" class=\"p-1.5 text-zinc-400 hover:text-white rounded hover:bg-[#2a2a2f]\" title=\"Quote\" data-i18n-title=\"docQuote\"><span class=\"text-lg leading-none\">&rdquo;</span></button>\n                    <div class=\"w-6 h-[1px] bg-borderSubtle\"></div>\n                    <button onclick=\"promptDocLink()\" class=\"p-1.5 text-zinc-400 hover:text-white rounded hover:bg-[#2a2a2f]\" title=\"Link\" data-i18n-title=\"toolLink\"><svg class=\"w-4 h-4\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71\"></path><path d=\"M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71\"></path></svg></button>\n                    <button onclick=\"document.execCommand('removeFormat')\" class=\"p-1.5 text-zinc-400 hover:text-white rounded hover:bg-[#2a2a2f] mt-auto\" title=\"Clear Formatting\" data-i18n-title=\"docClearFormatting\"><svg class=\"w-4 h-4\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M4 7V4h16v3\"></path><path d=\"M5 20h6\"></path><path d=\"M13 4L8 20\"></path><path d=\"M15 15l6 6\"></path><path d=\"M21 15l-6 6\"></path></svg></button>\n                </div>\n                <!-- Área de Escrita -->\n                <div id=\"doc-editor\" contenteditable=\"true\" class=\"flex-1 overflow-y-auto p-4 sm:p-8 text-zinc-200 text-sm leading-relaxed focus:outline-none prose prose-invert max-w-none\"></div>\n            </div>\n        </div>\n    </div>\n\n    <!-- SETTINGS MODAL -->\n    <div id=\"settings-modal\" class=\"fixed inset-0 bg-black/65 backdrop-blur-sm z-[250] flex items-center justify-center hidden p-2.5 sm:p-4\" onmousedown=\"if(event.target.id==='settings-modal') closeSettingsModal()\">\n        <div class=\"bg-[#18181b] border border-white/[0.08] rounded-2xl w-full max-w-[520px] max-h-[90dvh] sm:max-h-[88vh] flex flex-col card-shadow overflow-hidden\">\n            <div class=\"px-4 sm:px-5 py-3.5 sm:py-4 border-b border-white/[0.06] flex items-center justify-between shrink-0\">\n                <div>\n                    <h3 class=\"font-semibold text-sm text-zinc-100\" data-i18n=\"settings\">Settings</h3>\n                    <p class=\"text-[11px] text-zinc-500 mt-0.5\" data-i18n=\"settingsSubtitle\">Language, profile, local storage &amp; workspace data</p>\n                </div>\n                <button type=\"button\" onclick=\"closeSettingsModal()\" class=\"text-zinc-400 hover:text-zinc-200 p-1.5 rounded-lg hover:bg-white/[0.06] transition-colors\">\n                    <svg class=\"w-4 h-4\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"></line><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"></line></svg>\n                </button>\n            </div>\n\n            <div class=\"flex-1 overflow-y-auto p-4 sm:p-5 space-y-6\">\n                <!-- LANGUAGE -->\n                <section class=\"space-y-3\">\n                    <div class=\"text-[11px] font-semibold uppercase tracking-wider text-zinc-500\" data-i18n=\"languageSection\">Language</div>\n                    <div class=\"bg-white/[0.025] border border-white/[0.06] rounded-xl p-3.5 flex items-center justify-between gap-3\">\n                        <div>\n                            <div class=\"text-xs font-medium text-zinc-200\" data-i18n=\"interfaceLanguage\">Interface Language</div>\n                            <div class=\"text-[11px] text-zinc-500\" data-i18n=\"interfaceLanguageDesc\">Switch menus, labels, and notifications</div>\n                        </div>\n                        <div class=\"flex items-center bg-[#141416] border border-white/[0.08] rounded-lg p-0.5 shrink-0\">\n                            <button type=\"button\" id=\"lang-btn-en\" onclick=\"setLanguage('en')\" class=\"px-2.5 py-1 rounded-md text-[11px] font-medium transition-colors\">English</button>\n                            <button type=\"button\" id=\"lang-btn-pt\" onclick=\"setLanguage('pt-BR')\" class=\"px-2.5 py-1 rounded-md text-[11px] font-medium transition-colors\">PT-BR</button>\n                        </div>\n                    </div>\n                </section>\n\n                <!-- SOUND -->\n                <section class=\"space-y-3\">\n                    <div class=\"text-[11px] font-semibold uppercase tracking-wider text-zinc-500\" data-i18n=\"soundSection\">Sound</div>\n                    <div class=\"bg-white/[0.025] border border-white/[0.06] rounded-xl p-3.5 flex items-center justify-between gap-3\">\n                        <div>\n                            <div class=\"text-xs font-medium text-zinc-200\" data-i18n=\"cozySoundsTitle\">Cozy Sound Effects</div>\n                            <div class=\"text-[11px] text-zinc-500\" data-i18n=\"cozySoundsDesc\">Subtle tactile chimes for tasks, drops, and unsorted</div>\n                        </div>\n                        <label class=\"velmap-switch\" title=\"Cozy Sound Effects\" data-i18n-title=\"cozySoundsTitle\">\n                            <input type=\"checkbox\" id=\"settings-sounds-toggle\" class=\"sr-only\" onchange=\"setSoundsEnabled(this.checked)\">\n                            <span class=\"velmap-switch-track\">\n                                <span class=\"velmap-switch-thumb\"></span>\n                            </span>\n                        </label>\n                    </div>\n                </section>\n\n                <!-- PROFILE -->\n                <section class=\"space-y-3\">\n                    <div class=\"text-[11px] font-semibold uppercase tracking-wider text-zinc-500\" data-i18n=\"profileSection\">Profile</div>\n                    <div class=\"bg-white/[0.025] border border-white/[0.06] rounded-xl p-4 space-y-4\">\n                        <div class=\"flex items-center space-x-3.5\">\n                            <button type=\"button\" onclick=\"triggerPfpUpload()\" class=\"relative group w-14 h-14 rounded-full shrink-0 focus:outline-none\" title=\"Change profile photo\" data-i18n-title=\"changePfpTitle\">\n                                <div id=\"settings-avatar-preview\" class=\"w-14 h-14 rounded-full text-white font-semibold text-base flex items-center justify-center border border-white/10 overflow-hidden\" style=\"background-color:#4f6b8a\">U</div>\n                                <div class=\"absolute inset-0 rounded-full bg-black/55 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center\">\n                                    <svg class=\"w-4 h-4 text-white\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\n                                        <path d=\"M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z\"></path>\n                                        <circle cx=\"12\" cy=\"13\" r=\"4\"></circle>\n                                    </svg>\n                                </div>\n                            </button>\n                            <div class=\"flex-1 min-w-0 space-y-2\">\n                                <div>\n                                    <label for=\"settings-user-name-input\" class=\"block text-[11px] text-zinc-400 mb-1\" data-i18n=\"displayName\">Display Name</label>\n                                    <input type=\"text\" id=\"settings-user-name-input\" maxlength=\"40\" placeholder=\"Your name...\" data-i18n-placeholder=\"yourNamePlaceholder\" oninput=\"setProfileName(this.value)\" class=\"w-full bg-[#141416] text-xs text-zinc-100 px-3 py-2 rounded-lg border border-white/[0.08] focus:outline-none focus:border-white/25 transition-colors\">\n                                </div>\n                                <div class=\"flex items-center space-x-2\">\n                                    <button type=\"button\" onclick=\"triggerPfpUpload()\" class=\"px-2.5 py-1 rounded-md text-[11px] font-medium bg-white/[0.06] hover:bg-white/[0.12] text-zinc-200 border border-white/[0.08] transition-colors\" data-i18n=\"uploadPhoto\">Upload Photo</button>\n                                    <button type=\"button\" id=\"btn-remove-pfp\" onclick=\"removeUserPfp()\" class=\"hidden px-2.5 py-1 rounded-md text-[11px] text-zinc-400 hover:text-red-400 hover:bg-red-500/10 transition-colors\" data-i18n=\"removePhoto\">Remove Photo</button>\n                                </div>\n                            </div>\n                        </div>\n                        <div class=\"flex items-center justify-between pt-1\">\n                            <span class=\"text-[11px] text-zinc-400\" data-i18n=\"fallbackAccent\">Profile &amp; Avatar Color</span>\n                            <div class=\"flex items-center space-x-2\" id=\"settings-color-options\">\n                                <button type=\"button\" onclick=\"setProfileColor('#52525b')\" data-color=\"#52525b\" class=\"w-5 h-5 rounded-full bg-[#52525b] border border-white/20 hover:scale-110 transition-transform\" title=\"Zinc\"></button>\n                                <button type=\"button\" onclick=\"setProfileColor('#4f6b8a')\" data-color=\"#4f6b8a\" class=\"w-5 h-5 rounded-full bg-[#4f6b8a] border border-white/20 hover:scale-110 transition-transform\" title=\"Steel Blue\"></button>\n                                <button type=\"button\" onclick=\"setProfileColor('#4f8a5f')\" data-color=\"#4f8a5f\" class=\"w-5 h-5 rounded-full bg-[#4f8a5f] border border-white/20 hover:scale-110 transition-transform\" title=\"Sage Green\"></button>\n                                <button type=\"button\" onclick=\"setProfileColor('#8a7d4f')\" data-color=\"#8a7d4f\" class=\"w-5 h-5 rounded-full bg-[#8a7d4f] border border-white/20 hover:scale-110 transition-transform\" title=\"Muted Amber\"></button>\n                                <button type=\"button\" onclick=\"setProfileColor('#8a4f4f')\" data-color=\"#8a4f4f\" class=\"w-5 h-5 rounded-full bg-[#8a4f4f] border border-white/20 hover:scale-110 transition-transform\" title=\"Muted Rose\"></button>\n                                <button type=\"button\" onclick=\"setProfileColor('#6b538c')\" data-color=\"#6b538c\" class=\"w-5 h-5 rounded-full bg-[#6b538c] border border-white/20 hover:scale-110 transition-transform\" title=\"Muted Plum\"></button>\n                                <label id=\"settings-custom-color-label\" class=\"relative w-5 h-5 rounded-full border border-white/25 overflow-hidden cursor-pointer hover:scale-110 transition-transform flex items-center justify-center bg-[#27272a]\" title=\"Custom Color\">\n                                    <input type=\"color\" id=\"settings-custom-color-input\" value=\"#4f6b8a\" oninput=\"setProfileColor(this.value)\" onchange=\"setProfileColor(this.value)\" class=\"opacity-0 absolute inset-0 w-full h-full cursor-pointer\">\n                                    <svg class=\"w-3 h-3 text-zinc-200 pointer-events-none drop-shadow\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"></line><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"></line></svg>\n                                </label>\n                            </div>\n                        </div>\n                    </div>\n                </section>\n\n                <!-- STORAGE & CONTENTS -->\n                <section class=\"space-y-3\">\n                    <div class=\"flex items-center justify-between\">\n                        <span class=\"text-[11px] font-semibold uppercase tracking-wider text-zinc-500\" data-i18n=\"storageSection\">Storage &amp; Contents</span>\n                        <span id=\"storage-total-label\" class=\"text-xs font-medium text-zinc-300\" data-i18n=\"calculating\">Calculating...</span>\n                    </div>\n                    <div class=\"bg-white/[0.025] border border-white/[0.06] rounded-xl p-4 space-y-4\">\n                        <div>\n                            <div class=\"w-full h-2 rounded-full bg-white/[0.06] overflow-hidden flex\" id=\"storage-progress-bar\"></div>\n                            <div class=\"flex items-center justify-between mt-2 text-[11px] text-zinc-500\">\n                                <span id=\"storage-items-summary\">0 items stored locally</span>\n                                <span id=\"storage-quota-label\"></span>\n                            </div>\n                        </div>\n                        <div id=\"storage-breakdown-list\" class=\"divide-y divide-white/[0.05] text-xs\"></div>\n                    </div>\n                </section>\n\n                <!-- DEVICE SYNC -->\n                <section class=\"space-y-3\">\n                    <div class=\"text-[11px] font-semibold uppercase tracking-wider text-zinc-500\" data-i18n=\"deviceSyncSection\">Device-to-Device Sync</div>\n                    <div class=\"bg-white/[0.025] border border-white/[0.06] rounded-xl p-4 flex items-center justify-between gap-3\">\n                        <div>\n                            <div class=\"text-xs font-medium text-zinc-200\" data-i18n=\"syncAcrossDevices\">Sync Across Devices</div>\n                            <div class=\"text-[11px] text-zinc-500\" id=\"settings-sync-status\">Direct peer-to-peer (no server) or via .velmap file</div>\n                        </div>\n                        <button type=\"button\" onclick=\"closeSettingsModal(); openSyncModal();\" class=\"px-3 py-1.5 rounded-lg text-xs font-medium bg-white/[0.07] hover:bg-white/[0.12] text-zinc-100 border border-white/[0.08] transition-colors shrink-0\" data-i18n=\"openSyncBtn\">Open Sync</button>\n                    </div>\n                </section>\n\n                <!-- CLEAR OPTIONS -->\n                <section class=\"space-y-3\">\n                    <div class=\"text-[11px] font-semibold uppercase tracking-wider text-zinc-500\" data-i18n=\"cleanupSection\">Cleanup</div>\n                    <div class=\"bg-white/[0.025] border border-white/[0.06] rounded-xl divide-y divide-white/[0.05] overflow-hidden\">\n                        <div class=\"p-3.5 flex items-center justify-between gap-3\">\n                            <div>\n                                <div class=\"text-xs font-medium text-zinc-200\" data-i18n=\"emptyTrashTitle\">Empty Trash</div>\n                                <div class=\"text-[11px] text-zinc-500\" id=\"clear-trash-subtitle\">Permanently delete trashed cards</div>\n                            </div>\n                            <button type=\"button\" onclick=\"requestClearAction('trash')\" class=\"px-3 py-1.5 rounded-lg text-xs font-medium bg-white/[0.05] hover:bg-white/[0.1] text-zinc-300 border border-white/[0.06] transition-colors shrink-0\" data-i18n=\"emptyBtn\">Empty</button>\n                        </div>\n                        <div class=\"p-3.5 flex items-center justify-between gap-3\">\n                            <div>\n                                <div class=\"text-xs font-medium text-zinc-200\" data-i18n=\"clearUnsortedTitle\">Clear Unsorted</div>\n                                <div class=\"text-[11px] text-zinc-500\" id=\"clear-unsorted-subtitle\">Remove all cards in the Unsorted drawer</div>\n                            </div>\n                            <button type=\"button\" onclick=\"requestClearAction('unsorted')\" class=\"px-3 py-1.5 rounded-lg text-xs font-medium bg-white/[0.05] hover:bg-white/[0.1] text-zinc-300 border border-white/[0.06] transition-colors shrink-0\" data-i18n=\"clearBtn\">Clear</button>\n                        </div>\n                        <div class=\"p-3.5 space-y-3\">\n                            <div class=\"flex items-center justify-between gap-3\">\n                                <div>\n                                    <div class=\"text-xs font-medium text-red-400\" data-i18n=\"clearAllTitle\">Clear All App Data</div>\n                                    <div class=\"text-[11px] text-zinc-500\" data-i18n=\"clearAllDesc\">Delete all boards, cards, images, and connections</div>\n                                </div>\n                                <button type=\"button\" id=\"btn-clear-all-trigger\" onclick=\"requestClearAction('all')\" class=\"px-3 py-1.5 rounded-lg text-xs font-medium bg-red-500/10 hover:bg-red-500/20 text-red-400 border border-red-500/20 transition-colors shrink-0\" data-i18n=\"resetAppBtn\">Reset App</button>\n                            </div>\n                            <div id=\"clear-confirm-bar\" class=\"hidden bg-red-500/10 border border-red-500/20 rounded-lg p-3 flex items-center justify-between gap-2\">\n                                <span id=\"clear-confirm-text\" class=\"text-[11px] text-red-300\" data-i18n=\"areYouSure\">Are you sure? This cannot be undone.</span>\n                                <div class=\"flex items-center space-x-2 shrink-0\">\n                                    <button type=\"button\" onclick=\"cancelClearAction()\" class=\"px-2.5 py-1 rounded text-[11px] text-zinc-300 hover:bg-white/[0.08] transition-colors\" data-i18n=\"cancel\">Cancel</button>\n                                    <button type=\"button\" onclick=\"executeClearAction()\" class=\"px-2.5 py-1 rounded text-[11px] font-medium bg-red-500 hover:bg-red-600 text-white transition-colors\" data-i18n=\"confirm\">Confirm</button>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </section>\n            </div>\n        </div>\n    </div>\n\n    <!-- PFP CROP MODAL -->\n    <div id=\"pfp-crop-modal\" class=\"fixed inset-0 bg-black/75 backdrop-blur-sm z-[280] flex items-center justify-center hidden p-4\" onmousedown=\"if(event.target.id==='pfp-crop-modal') closePfpCropModal()\">\n        <div class=\"bg-[#18181b] border border-white/[0.08] rounded-2xl w-full max-w-[360px] flex flex-col card-shadow overflow-hidden\">\n            <div class=\"px-5 py-3.5 border-b border-white/[0.06] flex items-center justify-between\">\n                <div>\n                    <h3 class=\"font-semibold text-sm text-zinc-100\" data-i18n=\"cropPfpTitle\">Crop Profile Photo</h3>\n                    <p class=\"text-[11px] text-zinc-500\" data-i18n=\"cropPfpSubtitle\">Drag to reposition, slider to zoom</p>\n                </div>\n                <button type=\"button\" onclick=\"closePfpCropModal()\" class=\"text-zinc-400 hover:text-zinc-200 p-1 rounded-lg hover:bg-white/[0.06] transition-colors\">\n                    <svg class=\"w-4 h-4\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"></line><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"></line></svg>\n                </button>\n            </div>\n\n            <div class=\"p-5 flex flex-col items-center space-y-4\">\n                <div id=\"pfp-crop-stage\" class=\"relative w-[260px] h-[260px] rounded-xl bg-[#111113] overflow-hidden border border-white/[0.08] cursor-grab active:cursor-grabbing select-none touch-none\">\n                    <canvas id=\"pfp-crop-canvas\" width=\"260\" height=\"260\" class=\"w-full h-full block\"></canvas>\n                    <div class=\"pointer-events-none absolute inset-0 flex items-center justify-center\">\n                        <div class=\"w-[220px] h-[220px] rounded-full border-2 border-white/80 shadow-[0_0_0_9999px_rgba(12,12,15,0.68)]\"></div>\n                    </div>\n                </div>\n\n                <div class=\"w-full flex items-center space-x-3\">\n                    <svg class=\"w-3.5 h-3.5 text-zinc-500 shrink-0\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"11\" cy=\"11\" r=\"8\"></circle><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"></line><line x1=\"8\" y1=\"11\" x2=\"14\" y2=\"11\"></line></svg>\n                    <input type=\"range\" id=\"pfp-crop-zoom\" min=\"1\" max=\"3\" step=\"0.01\" value=\"1\" oninput=\"onPfpCropZoomChange(this.value)\" class=\"flex-1 accent-zinc-200 h-1.5 bg-white/10 rounded-lg cursor-pointer\">\n                    <svg class=\"w-4 h-4 text-zinc-400 shrink-0\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"11\" cy=\"11\" r=\"8\"></circle><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"></line><line x1=\"11\" y1=\"8\" x2=\"11\" y2=\"14\"></line><line x1=\"8\" y1=\"11\" x2=\"14\" y2=\"11\"></line></svg>\n                    <button type=\"button\" onclick=\"resetPfpCrop()\" class=\"text-[11px] text-zinc-400 hover:text-zinc-200 px-1.5 py-0.5 rounded hover:bg-white/[0.06] transition-colors\" data-i18n=\"reset\">Reset</button>\n                </div>\n            </div>\n\n            <div class=\"px-5 py-3.5 border-t border-white/[0.06] flex items-center justify-end space-x-2 bg-white/[0.015]\">\n                <button type=\"button\" onclick=\"closePfpCropModal()\" class=\"px-3 py-1.5 rounded-lg text-xs text-zinc-300 hover:bg-white/[0.06] transition-colors\" data-i18n=\"cancel\">Cancel</button>\n                <button type=\"button\" onclick=\"applyPfpCrop()\" class=\"px-3.5 py-1.5 rounded-lg text-xs font-medium bg-zinc-100 hover:bg-white text-zinc-900 transition-colors\" data-i18n=\"applyPhoto\">Apply Photo</button>\n            </div>\n        </div>\n    </div>\n\n    <!-- SYNC MODAL (P2P & LOCAL FILE - ZERO SERVER) -->\n    <div id=\"sync-modal\" class=\"fixed inset-0 bg-black/70 backdrop-blur-sm z-[260] flex items-center justify-center hidden p-2.5 sm:p-4\" onmousedown=\"if(event.target.id==='sync-modal') closeSyncModal()\">\n        <div class=\"bg-[#18181b] border border-white/[0.08] rounded-2xl w-full max-w-[560px] max-h-[92dvh] sm:max-h-[90vh] flex flex-col card-shadow overflow-hidden\">\n            <div class=\"px-4 sm:px-5 py-3.5 sm:py-4 border-b border-white/[0.06] flex items-center justify-between gap-2 shrink-0\">\n                <div class=\"min-w-0\">\n                    <h3 class=\"font-semibold text-sm text-zinc-100\" data-i18n=\"syncModalTitle\">Velmap Sync — Device to Device</h3>\n                    <p class=\"text-[11px] text-zinc-500 mt-0.5\" data-i18n=\"syncModalSubtitle\">100% serverless: your data stays only on your devices</p>\n                </div>\n                <div class=\"flex items-center space-x-1.5 shrink-0\">\n                    <button type=\"button\" onclick=\"toggleLanguage()\" id=\"sync-lang-toggle\" class=\"px-2 py-1 rounded-md text-[10px] font-semibold bg-white/[0.05] hover:bg-white/[0.1] text-zinc-300 border border-white/[0.08] transition-colors\">EN / PT</button>\n                    <button type=\"button\" onclick=\"closeSyncModal()\" class=\"text-zinc-400 hover:text-zinc-200 p-1.5 rounded-lg hover:bg-white/[0.06] transition-colors\">\n                        <svg class=\"w-4 h-4\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"></line><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"></line></svg>\n                    </button>\n                </div>\n            </div>\n\n            <div class=\"px-3.5 sm:px-5 pt-3 border-b border-white/[0.06] flex flex-wrap items-center justify-between gap-2 shrink-0 bg-white/[0.015]\">\n                <div class=\"flex items-center space-x-1\">\n                    <button type=\"button\" id=\"sync-tab-p2p\" onclick=\"switchSyncTab('p2p')\" class=\"px-2.5 sm:px-3 py-2 text-xs font-medium text-zinc-100 border-b-2 border-zinc-100\" data-i18n=\"syncTabP2P\">Direct P2P (WebRTC)</button>\n                    <button type=\"button\" id=\"sync-tab-file\" onclick=\"switchSyncTab('file')\" class=\"px-2.5 sm:px-3 py-2 text-xs font-medium text-zinc-400 hover:text-zinc-200 border-b-2 border-transparent\" data-i18n=\"syncTabFile\">File / Syncthing</button>\n                </div>\n                <div id=\"sync-connection-pill\" class=\"text-[11px] text-zinc-400 flex items-center space-x-1.5 pb-2\">\n                    <span id=\"sync-modal-dot\" class=\"w-2 h-2 rounded-full bg-zinc-500\"></span>\n                    <span id=\"sync-modal-status\">Offline (Local)</span>\n                </div>\n            </div>\n\n            <div class=\"flex-1 overflow-y-auto p-3.5 sm:p-5 space-y-5\">\n                <!-- CONNECTED BANNER -->\n                <div id=\"p2p-connected-panel\" class=\"hidden bg-emerald-500/10 border border-emerald-500/20 rounded-xl p-3.5 sm:p-4 space-y-3\">\n                    <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n                        <div>\n                            <div class=\"text-xs font-semibold text-emerald-300\" data-i18n=\"p2pConnectedTitle\">Connected directly to another device</div>\n                            <div class=\"text-[11px] text-emerald-200/70 mt-0.5\" id=\"p2p-last-sync-label\" data-i18n=\"p2pConnectedDesc\">Changes sync automatically in real time.</div>\n                        </div>\n                        <div class=\"flex items-center space-x-2 shrink-0\">\n                            <button type=\"button\" onclick=\"sendP2PSnapshot(true)\" class=\"px-2.5 py-1.5 rounded-lg text-[11px] font-medium bg-emerald-500/20 hover:bg-emerald-500/30 text-emerald-200 border border-emerald-500/30 transition-colors\" data-i18n=\"syncNow\">Sync Now</button>\n                            <button type=\"button\" onclick=\"disconnectP2P()\" class=\"px-2.5 py-1.5 rounded-lg text-[11px] text-zinc-300 hover:bg-white/[0.08] border border-white/[0.08] transition-colors\" data-i18n=\"disconnect\">Disconnect</button>\n                        </div>\n                    </div>\n                </div>\n\n                <!-- P2P PANEL -->\n                <div id=\"sync-panel-p2p\" class=\"space-y-4\">\n                    <!-- THIS DEVICE & MAIN MACHINE ROLE -->\n                    <div class=\"bg-white/[0.025] border border-white/[0.06] rounded-xl p-3.5 sm:p-4 space-y-2.5\">\n                        <div class=\"flex items-center justify-between gap-2\">\n                            <span class=\"text-[11px] font-semibold uppercase tracking-wider text-zinc-400\" data-i18n=\"thisDeviceLabel\">This Device</span>\n                            <div class=\"flex items-center gap-1.5\">\n                                <span id=\"sync-primary-badge\" class=\"hidden px-2 py-0.5 rounded-md text-[10px] font-semibold bg-amber-500/15 text-amber-300 border border-amber-500/25\" data-i18n=\"mainMachineBadge\">Main Machine</span>\n                                <button type=\"button\" id=\"btn-toggle-primary-machine\" onclick=\"togglePrimaryMachine()\" class=\"px-2 py-0.5 rounded-md text-[10px] font-medium bg-white/[0.06] hover:bg-white/[0.12] text-zinc-300 border border-white/[0.08] transition-colors\" data-i18n=\"setMainMachineBtn\">Set as Main Machine</button>\n                            </div>\n                        </div>\n                        <div class=\"flex items-center gap-2\">\n                            <input type=\"text\" id=\"sync-device-name-input\" maxlength=\"36\" onchange=\"updateLocalDeviceName(this.value)\" placeholder=\"Device name...\" data-i18n-placeholder=\"deviceNamePlaceholder\" class=\"flex-1 min-w-0 bg-[#131316] text-xs text-zinc-100 px-2.5 py-1.5 rounded-lg border border-white/[0.08] focus:outline-none focus:border-white/25\">\n                            <span id=\"sync-device-platform-pill\" class=\"px-2 py-1 rounded-md text-[10px] font-medium bg-white/[0.04] text-zinc-400 border border-white/[0.06] uppercase shrink-0\">PC</span>\n                        </div>\n                    </div>\n\n                    <!-- SAVED & SYNCED DEVICES (PERSISTENT - NO REPEATED INVITES) -->\n                    <div id=\"sync-saved-devices-section\" class=\"bg-white/[0.025] border border-white/[0.06] rounded-xl p-3.5 sm:p-4 space-y-2.5\">\n                        <div class=\"flex items-center justify-between gap-2\">\n                            <div class=\"text-xs font-semibold text-zinc-200\" data-i18n=\"savedDevicesTitle\">Synced Devices</div>\n                            <span id=\"sync-saved-count\" class=\"text-[10px] text-zinc-500 font-medium\">0</span>\n                        </div>\n                        <div id=\"sync-saved-devices-list\" class=\"space-y-2\"></div>\n                    </div>\n\n                    <!-- ONE-TIME PAIRING CODE -->\n                    <div class=\"bg-white/[0.025] border border-white/[0.06] rounded-xl p-3.5 sm:p-4 space-y-3\">\n                        <div class=\"flex items-start justify-between gap-2\">\n                            <div>\n                                <div class=\"text-xs font-semibold text-zinc-200\" data-i18n=\"pairOnceTitle\">Pair a New Device (One-Time)</div>\n                                <div class=\"text-[11px] text-zinc-500 mt-0.5\" data-i18n=\"pairOnceDesc\">Pair once via short code. Future visits reconnect automatically without new invites.</div>\n                            </div>\n                            <button type=\"button\" onclick=\"createPairRoomCode()\" class=\"px-3 py-1.5 rounded-lg text-xs font-medium bg-zinc-100 hover:bg-white text-zinc-900 transition-colors shrink-0\" data-i18n=\"createPairCodeBtn\">New Code</button>\n                        </div>\n\n                        <div id=\"sync-pair-code-box\" class=\"hidden pt-2 border-t border-white/[0.06] space-y-2\">\n                            <div class=\"flex items-center justify-between gap-2 bg-[#131316] border border-white/[0.08] rounded-lg px-3 py-2\">\n                                <div>\n                                    <div class=\"text-[10px] text-zinc-500 uppercase tracking-wider\" data-i18n=\"pairCodeLabel\">Enter this code on the other device</div>\n                                    <div id=\"sync-pair-code-display\" class=\"text-base font-mono font-semibold tracking-widest text-zinc-100 mt-0.5\">VM-0000</div>\n                                </div>\n                                <button type=\"button\" onclick=\"copyPairCodeText()\" class=\"px-2.5 py-1.5 rounded-lg text-[11px] bg-white/[0.07] hover:bg-white/[0.12] text-zinc-200 border border-white/[0.08] shrink-0\" data-i18n=\"copy\">Copy</button>\n                            </div>\n                            <div id=\"sync-pair-waiting-hint\" class=\"text-[11px] text-zinc-400\" data-i18n=\"pairingWaitingStatus\">Waiting for your other device to enter this code...</div>\n                        </div>\n\n                        <div class=\"flex flex-wrap sm:flex-nowrap gap-2 pt-1 border-t border-white/[0.05]\">\n                            <input type=\"text\" id=\"sync-join-pair-input\" maxlength=\"16\" placeholder=\"Code (e.g. VM-48K9)\" data-i18n-placeholder=\"enterPairCodePlaceholder\" onkeydown=\"if(event.key==='Enter') joinPairRoomCode()\" class=\"flex-1 min-w-[140px] bg-[#131316] text-xs font-mono uppercase text-zinc-200 px-2.5 py-1.5 rounded-lg border border-white/[0.08] focus:outline-none focus:border-white/25\">\n                            <button type=\"button\" onclick=\"joinPairRoomCode()\" class=\"px-3 py-1.5 rounded-lg text-xs font-medium bg-emerald-500 hover:bg-emerald-400 text-zinc-950 transition-colors shrink-0\" data-i18n=\"pairConnectBtn\">Pair Device</button>\n                        </div>\n                    </div>\n\n                    <!-- MANUAL / OFFLINE QR PAIRING FALLBACK -->\n                    <details id=\"sync-manual-qr-details\" class=\"bg-white/[0.015] border border-white/[0.05] rounded-xl overflow-hidden\">\n                        <summary class=\"px-3.5 py-2.5 text-[11px] font-medium text-zinc-400 hover:text-zinc-200 cursor-pointer select-none flex items-center justify-between\" data-i18n=\"manualQrSummary\">\n                            Manual QR / Offline Invite (VM1 &amp; VM2 Fallback)\n                        </summary>\n                        <div class=\"p-3.5 pt-2 space-y-3 border-t border-white/[0.05]\">\n                            <div class=\"bg-white/[0.025] border border-white/[0.06] rounded-xl p-3 space-y-3\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <div>\n                                        <div class=\"text-xs font-semibold text-zinc-200\" data-i18n=\"p2pStep1Title\">1. Start on this device (Create Invite)</div>\n                                        <div class=\"text-[11px] text-zinc-500\" data-i18n=\"p2pStep1Desc\">Use on either device to initiate the connection</div>\n                                    </div>\n                                    <button type=\"button\" onclick=\"startP2PHost()\" class=\"px-3 py-1.5 rounded-lg text-xs font-medium bg-zinc-100 hover:bg-white text-zinc-900 transition-colors shrink-0\" data-i18n=\"createInvite\">Create Invite</button>\n                                </div>\n\n                                <div id=\"p2p-host-box\" class=\"hidden space-y-3 pt-2 border-t border-white/[0.06]\">\n                                    <div class=\"flex flex-col sm:flex-row gap-3 items-center\">\n                                        <div id=\"p2p-offer-qr\" class=\"bg-white p-2 rounded-lg shrink-0 hidden\"></div>\n                                        <div class=\"flex-1 w-full space-y-2\">\n                                            <label class=\"block text-[11px] text-zinc-400\" data-i18n=\"p2pOfferLabel\">Send this code (or QR) to your other device:</label>\n                                            <div class=\"flex gap-2\">\n                                                <input type=\"text\" id=\"p2p-offer-output\" readonly class=\"flex-1 min-w-0 bg-[#131316] text-[11px] font-mono text-zinc-300 px-2.5 py-1.5 rounded-lg border border-white/[0.08] focus:outline-none\">\n                                                <button type=\"button\" onclick=\"copySyncText('p2p-offer-output')\" class=\"px-2.5 py-1.5 rounded-lg text-[11px] bg-white/[0.07] hover:bg-white/[0.12] text-zinc-200 border border-white/[0.08] shrink-0\" data-i18n=\"copy\">Copy</button>\n                                            </div>\n                                        </div>\n                                    </div>\n                                    <div class=\"space-y-1.5 pt-2 border-t border-white/[0.05]\">\n                                        <label class=\"block text-[11px] text-zinc-400\" data-i18n-html=\"p2pAnswerInputLabel\">Paste the Answer code (<code class=\"text-zinc-300\">VM2:...</code>) generated by the other device:</label>\n                                        <div class=\"flex flex-wrap sm:flex-nowrap gap-2\">\n                                            <input type=\"text\" id=\"p2p-answer-input\" placeholder=\"Paste VM2:... here\" data-i18n-placeholder=\"pasteVm2Placeholder\" class=\"flex-1 min-w-[140px] bg-[#131316] text-[11px] font-mono text-zinc-200 px-2.5 py-1.5 rounded-lg border border-white/[0.08] focus:outline-none focus:border-white/25\">\n                                            <button type=\"button\" id=\"btn-scan-answer-qr\" onclick=\"startQrScanner('p2p-answer-input')\" class=\"hidden px-2.5 py-1.5 rounded-lg text-[11px] bg-white/[0.06] hover:bg-white/[0.1] text-zinc-200 border border-white/[0.08] shrink-0\" data-i18n=\"scanQr\">Scan QR</button>\n                                            <button type=\"button\" onclick=\"acceptP2PAnswer()\" class=\"px-3 py-1.5 rounded-lg text-xs font-medium bg-emerald-500 hover:bg-emerald-400 text-zinc-950 transition-colors shrink-0\" data-i18n=\"connect\">Connect</button>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n\n                            <div class=\"bg-white/[0.025] border border-white/[0.06] rounded-xl p-3 space-y-3\">\n                                <div>\n                                    <div class=\"text-xs font-semibold text-zinc-200\" data-i18n=\"p2pStep2Title\">2. Join with an Invite from another device</div>\n                                    <div class=\"text-[11px] text-zinc-500\" data-i18n-html=\"p2pStep2Desc\">Paste the <code class=\"text-zinc-400\">VM1:...</code> code (or scan the QR) to generate an answer</div>\n                                </div>\n                                <div class=\"flex flex-wrap sm:flex-nowrap gap-2\">\n                                    <input type=\"text\" id=\"p2p-remote-offer-input\" placeholder=\"Paste VM1:... here\" data-i18n-placeholder=\"pasteVm1Placeholder\" class=\"flex-1 min-w-[140px] bg-[#131316] text-[11px] font-mono text-zinc-200 px-2.5 py-1.5 rounded-lg border border-white/[0.08] focus:outline-none focus:border-white/25\">\n                                    <button type=\"button\" id=\"btn-scan-offer-qr\" onclick=\"startQrScanner('p2p-remote-offer-input')\" class=\"hidden px-2.5 py-1.5 rounded-lg text-[11px] bg-white/[0.06] hover:bg-white/[0.1] text-zinc-200 border border-white/[0.08] shrink-0\" data-i18n=\"scanQr\">Scan QR</button>\n                                    <button type=\"button\" onclick=\"acceptP2POffer()\" class=\"px-3 py-1.5 rounded-lg text-xs font-medium bg-white/[0.08] hover:bg-white/[0.14] text-zinc-100 border border-white/[0.08] transition-colors shrink-0\" data-i18n=\"createAnswer\">Create Answer</button>\n                                </div>\n\n                                <div id=\"p2p-join-box\" class=\"hidden space-y-2 pt-2 border-t border-white/[0.06]\">\n                                    <div class=\"flex flex-col sm:flex-row gap-3 items-center\">\n                                        <div id=\"p2p-answer-qr\" class=\"bg-white p-2 rounded-lg shrink-0 hidden\"></div>\n                                        <div class=\"flex-1 w-full space-y-1.5\">\n                                            <label class=\"block text-[11px] text-zinc-400\" data-i18n-html=\"p2pAnswerOutLabel\">Send this Answer (<code class=\"text-zinc-300\">VM2:...</code>) back to Device 1:</label>\n                                            <div class=\"flex gap-2\">\n                                                <input type=\"text\" id=\"p2p-answer-output\" readonly class=\"flex-1 min-w-0 bg-[#131316] text-[11px] font-mono text-zinc-300 px-2.5 py-1.5 rounded-lg border border-white/[0.08] focus:outline-none\">\n                                                <button type=\"button\" onclick=\"copySyncText('p2p-answer-output')\" class=\"px-2.5 py-1.5 rounded-lg text-[11px] bg-white/[0.07] hover:bg-white/[0.12] text-zinc-200 border border-white/[0.08] shrink-0\" data-i18n=\"copy\">Copy</button>\n                                            </div>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                    </details>\n\n                    <!-- CAMERA QR SCANNER OVERLAY -->\n                    <div id=\"qr-scanner-box\" class=\"hidden bg-[#131316] border border-white/[0.1] rounded-xl p-3 space-y-2\">\n                        <div class=\"flex items-center justify-between\">\n                            <span class=\"text-xs font-medium text-zinc-200\" data-i18n=\"qrScannerTitle\">Point camera at the QR Code</span>\n                            <button type=\"button\" onclick=\"stopQrScanner()\" class=\"text-[11px] text-zinc-400 hover:text-zinc-200 px-2 py-0.5 rounded hover:bg-white/[0.08]\" data-i18n=\"closeCamera\">Close camera</button>\n                        </div>\n                        <video id=\"qr-scanner-video\" playsinline autoplay muted class=\"w-full max-h-56 rounded-lg bg-black object-cover\"></video>\n                    </div>\n                </div>\n\n                <!-- FILE / SYNCTHING PANEL -->\n                <div id=\"sync-panel-file\" class=\"hidden space-y-4\">\n                    <div class=\"text-[11px] text-zinc-400 leading-relaxed bg-white/[0.025] border border-white/[0.06] rounded-xl p-3.5\" data-i18n-html=\"fileSyncIntroHtml\">\n                        Ideal for syncing across your devices with <strong class=\"text-zinc-200\">Syncthing</strong>, <strong class=\"text-zinc-200\">LocalSend</strong>, or file sharing: when importing a <code class=\"text-zinc-300\">.velmap</code> file, the app <strong class=\"text-zinc-200\">merges</strong> changes from both devices while keeping the latest version of each card.\n                    </div>\n\n                    <div class=\"bg-white/[0.025] border border-white/[0.06] rounded-xl divide-y divide-white/[0.05] overflow-hidden\">\n                        <div class=\"p-3.5 sm:p-4 flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n                            <div>\n                                <div class=\"text-xs font-medium text-zinc-200\" data-i18n=\"exportPackageTitle\">Export .velmap Package</div>\n                                <div class=\"text-[11px] text-zinc-500\" data-i18n=\"exportPackageDesc\">Saves boards, cards, tasks, connections, images, and profile</div>\n                            </div>\n                            <button type=\"button\" onclick=\"exportVelmapFile()\" class=\"px-3 py-1.5 rounded-lg text-xs font-medium bg-zinc-100 hover:bg-white text-zinc-900 transition-colors shrink-0 self-start sm:self-auto\" data-i18n=\"exportBtn\">Export</button>\n                        </div>\n                        <div class=\"p-3.5 sm:p-4 flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n                            <div>\n                                <div class=\"text-xs font-medium text-zinc-200\" data-i18n=\"importPackageTitle\">Import &amp; Merge .velmap</div>\n                                <div class=\"text-[11px] text-zinc-500\" data-i18n=\"importPackageDesc\">Combines the file from another device without erasing local work</div>\n                            </div>\n                            <button type=\"button\" onclick=\"document.getElementById('velmap-import-input').click()\" class=\"px-3 py-1.5 rounded-lg text-xs font-medium bg-white/[0.07] hover:bg-white/[0.12] text-zinc-200 border border-white/[0.08] transition-colors shrink-0 self-start sm:self-auto\" data-i18n=\"importBtn\">Import</button>\n                        </div>\n                    </div>\n\n                    <div id=\"linked-file-section\" class=\"bg-white/[0.025] border border-white/[0.06] rounded-xl p-3.5 sm:p-4 space-y-3\">\n                        <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-3\">\n                            <div>\n                                <div class=\"text-xs font-medium text-zinc-200\" data-i18n=\"linkedFileTitle\">Linked File (Synced Folder / Syncthing)</div>\n                                <div class=\"text-[11px] text-zinc-500\" id=\"linked-file-name\" data-i18n=\"noLinkedFile\">No file linked (supported browsers)</div>\n                            </div>\n                            <div class=\"flex items-center gap-2 shrink-0 self-start sm:self-auto\">\n                                <button type=\"button\" id=\"btn-reconnect-linked-file\" onclick=\"reconnectPersistedSyncFile()\" class=\"hidden px-3 py-1.5 rounded-lg text-xs font-medium bg-emerald-500/20 hover:bg-emerald-500/30 text-emerald-200 border border-emerald-500/30 transition-colors\" data-i18n=\"reconnectFileBtn\">Reconnect File</button>\n                                <button type=\"button\" onclick=\"linkLocalSyncFile()\" class=\"px-3 py-1.5 rounded-lg text-xs font-medium bg-white/[0.07] hover:bg-white/[0.12] text-zinc-200 border border-white/[0.08] transition-colors\" data-i18n=\"linkFileBtn\">Link File</button>\n                            </div>\n                        </div>\n                        <div id=\"linked-file-actions\" class=\"hidden flex flex-wrap items-center justify-between gap-2 pt-2 border-t border-white/[0.06]\">\n                            <label class=\"flex items-center space-x-2 text-[11px] text-zinc-300 cursor-pointer\">\n                                <input type=\"checkbox\" id=\"linked-file-autosave\" class=\"rounded border-zinc-600 bg-transparent\" checked>\n                                <span data-i18n=\"autoSaveFile\">Auto-save changes to file</span>\n                            </label>\n                            <div class=\"flex items-center space-x-2\">\n                                <button type=\"button\" onclick=\"loadFromLinkedSyncFile()\" class=\"px-2.5 py-1 rounded-md text-[11px] bg-white/[0.06] hover:bg-white/[0.1] text-zinc-200 border border-white/[0.08]\" data-i18n=\"readAndMerge\">Read &amp; Merge</button>\n                                <button type=\"button\" onclick=\"saveToLinkedSyncFile(true)\" class=\"px-2.5 py-1 rounded-md text-[11px] bg-white/[0.06] hover:bg-white/[0.1] text-zinc-200 border border-white/[0.08]\" data-i18n=\"saveNow\">Save Now</button>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n\n    <!-- TOAST -->\n    <div id=\"toast\" class=\"fixed bottom-5 right-5 bg-[#1d1d20] border border-white/[0.08] text-zinc-200 px-3.5 py-2.5 rounded-lg shadow-xl z-[300] transform translate-y-20 opacity-0 transition-all duration-300 flex items-center space-x-2.5 text-xs pointer-events-none\">\n        <svg class=\"w-4 h-4 text-zinc-300 shrink-0\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg>\n        <span id=\"toast-msg\">Done</span>\n    </div>\n\n    <!-- Hidden File Inputs -->\n    <input type=\"file\" id=\"image-file-input\" accept=\"image/*,video/*\" multiple class=\"hidden\" onchange=\"handleFileInput(event)\">\n    <input type=\"file\" id=\"icon-file-input\" accept=\"image/*\" class=\"hidden\">\n    <input type=\"file\" id=\"pfp-file-input\" accept=\"image/*\" class=\"hidden\" onchange=\"handlePfpFileSelect(event)\">\n    <input type=\"file\" id=\"velmap-import-input\" accept=\".velmap,.json\" class=\"hidden\" onchange=\"importVelmapFile(event)\">";
